import numpy as np, mujoco, rcb_dtb, os, sys
from scipy.spatial.transform import Rotation as Rot
from PIL import Image
np.set_printoptions(precision=4,suppress=True)
class Controller:
 def __init__(self):
  self.s=s=rcb_dtb.Session(); self.m=s.model; self.d=s.data
  self.kd=mujoco.MjData(self.m);self.bid=self.m.body('palmleft_hand_C_MC').id
  self.q=rcb_dtb.INIT_Q.copy();self.s.record_start()
 def pose(self):return self.d.xpos[self.bid].copy(),self.d.xmat[self.bid].reshape(3,3).copy()
 def obj(self):return self.d.xpos[self.s._obj].copy(),self.d.xmat[self.s._obj].reshape(3,3).copy()
 def ik(self,p,R,q=None):
  q=self.q.copy() if q is None else q.copy();d=self.kd;m=self.m
  for _ in range(70):
   d.qpos[self.s._jq]=q;mujoco.mj_forward(m,d)
   e=np.r_[p-d.xpos[self.bid],Rot.from_matrix(R@d.xmat[self.bid].reshape(3,3).T).as_rotvec()]
   if np.linalg.norm(e)<1e-5:break
   jp=np.zeros((3,m.nv));jr=jp.copy();mujoco.mj_jacBody(m,d,jp,jr,self.bid)
   J=np.r_[jp[:,:7],jr[:,:7]]; dq=J.T@np.linalg.solve(J@J.T+np.eye(6)*1e-5,e)
   dq=np.clip(dq,-.15,.15);q[:7]=np.clip(q[:7]+dq,self.s.lower[:7],self.s.upper[:7])
  return q
 def step(self,q):self.q=q.copy();return self.s.step(q)
 def move(self,p,R,hand=None,n=120):
  start=self.q.copy(); end=self.ik(p,R)
  if hand is not None:end[7:]=hand
  for t in range(n):
   a=(t+1)/n;a=a*a*(3-2*a);self.step(start*(1-a)+end*a)
  return self.s.progress()
 def hold(self,n=60):
  for _ in range(n):self.step(self.q)
 def snap(self,name):
  print(name,self.s.progress(),'palm',self.pose()[0],'obj',self.obj()[0],flush=True)
  for cam in ['front','side','top']:Image.fromarray(self.s.render(cam)).save('/app/output/'+name+'_'+cam+'.png')
 def contacts(self):
  for c in self.d.contact:
   n=[self.m.geom(g).name for g in c.geom]
   if any(x.startswith('object_') for x in n):print(n,round(c.dist,4))
def hand(f=1.2, thumb=[1.2,0,.8,0,1.]):
 h=np.zeros(22);h[:5]=thumb
 for k in [5,9,13,18]:h[k:k+4]=[f,0,f,f]
 return h

def run():
 c=Controller();s=c.s
 R=np.array([[0,1,0],[0,0,-1],[-1,0,0.]])
 c.move(np.array([.11,.18,.70]),R,n=120)
 c.move(np.array([.11,.18,.595]),R,n=150)
 c.snap('approach')
 c.move(c.pose()[0],R,hand(),n=150);c.hold(90);c.snap('grasp');c.contacts()
 c.move(c.pose()[0]+[0,0,.12],R,n=180);c.hold(90);c.snap('lift');c.contacts()
 A=s.record_stop();np.save('/app/output/test.npy',A)
if __name__=='__main__':run()
